package com.example.admission.common.jwt; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService { @Value("${jwt.secret}") private String secret; private SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public Claims extractAllClaims(String token){return Jwts.parser().verifyWith(key()).build().parseSignedClaims(token).getPayload();} public boolean isTokenValid(String token){try{return extractAllClaims(token).getExpiration().after(new Date());}catch(JwtException|IllegalArgumentException e){return false;}} }
